//! Client bindings: one module per protocol XML, generated by wayland-scanner.
//!
//! Each module holds that protocol's interface modules (`bardo_window_v1::bardo_window_v1`,
//! ...), as wayland-protocols lays its own out. An enum another protocol owns is named through
//! that protocol's interface module, which the generating module imports.

/// Generates one protocol's client module with the interfaces it builds on in scope.
macro_rules! client_protocol {
    ($(#[$doc:meta])* $name:ident, $path:literal, [$($imports:path),*]) => {
        $(#[$doc])*
        pub mod $name {
            #![allow(dead_code, non_camel_case_types, unused_unsafe, unused_variables)]
            #![allow(non_upper_case_globals, non_snake_case, unused_imports)]
            #![allow(missing_docs, missing_debug_implementations, clippy::all)]

            use wayland_client;
            use wayland_client::protocol::*;
            $(use $imports::{*};)*

            /// The protocol's interface descriptions.
            pub mod __interfaces {
                use wayland_client::protocol::__interfaces::*;
                $(use $imports::{__interfaces::*};)*
                wayland_scanner::generate_interfaces!($path);
            }
            use self::__interfaces::*;

            wayland_scanner::generate_client_code!($path);
            // The scanner reads the XML inside a macro, which rustc's dependency list does not
            // record; including the bytes does, so a change to the XML alone rebuilds the crate.
            const _: &[u8] = include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/", $path));
        }
    };
}

client_protocol!(
    /// `bardo-window-v1.xml`: what an app says about its toplevel.
    bardo_window_v1,
    "protocols/bardo-window-v1.xml",
    [wayland_protocols::xdg::shell::client]
);

client_protocol!(
    /// `bardo-sensitive-v1.xml`: surfaces and regions kept from agents and capture.
    bardo_sensitive_v1,
    "protocols/bardo-sensitive-v1.xml",
    []
);

client_protocol!(
    /// `bardo-agent-v1.xml`: agent leases.
    bardo_agent_v1,
    "protocols/bardo-agent-v1.xml",
    [
        wayland_protocols::ext::foreign_toplevel_list::v1::client,
        wayland_protocols::ext::image_capture_source::v1::client
    ]
);

client_protocol!(
    /// `bardo-trusted-surface-v1.xml`: surfaces only the person can answer.
    bardo_trusted_surface_v1,
    "protocols/bardo-trusted-surface-v1.xml",
    []
);

client_protocol!(
    /// `bardo-desktop-v1.xml`: the compositor's model of apps, windows and Spaces.
    bardo_desktop_v1,
    "protocols/bardo-desktop-v1.xml",
    [
        wayland_protocols::ext::foreign_toplevel_list::v1::client,
        crate::client::bardo_window_v1,
        crate::client::bardo_sensitive_v1,
        crate::client::bardo_agent_v1
    ]
);

client_protocol!(
    /// `bardo-shell-v1.xml`: the shell's surface roles and system events.
    bardo_shell_v1,
    "protocols/bardo-shell-v1.xml",
    [
        wayland_protocols::ext::image_capture_source::v1::client,
        crate::client::bardo_desktop_v1
    ]
);
